-- Metadata only. No financial document, local profile or Auth0 session is imported.
CREATE TABLE finanzas.registry_state(singleton boolean PRIMARY KEY CHECK(singleton),revision bigint NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991));
INSERT INTO finanzas.registry_state VALUES(true,0);
CREATE TABLE finanzas.app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),revision bigint NOT NULL DEFAULT 0 CHECK(revision BETWEEN 0 AND 9007199254740991),authorization_epoch bigint NOT NULL DEFAULT 0 CHECK(authorization_epoch>=0),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')));
CREATE TABLE finanzas.external_identity(issuer text COLLATE "C" NOT NULL CHECK(issuer LIKE 'https://%/'),subject text COLLATE "C" NOT NULL CHECK(length(subject) BETWEEN 1 AND 256),user_id uuid NOT NULL REFERENCES finanzas.app_user ON DELETE RESTRICT,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),PRIMARY KEY(issuer,subject));
CREATE TABLE finanzas.profile(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL CHECK(length(label) BETWEEN 1 AND 200),revision bigint NOT NULL DEFAULT 0 CHECK(revision BETWEEN 0 AND 9007199254740991),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','blocked')));
CREATE TABLE finanzas.profile_owner(profile_id uuid PRIMARY KEY REFERENCES finanzas.profile ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES finanzas.app_user ON DELETE RESTRICT,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),UNIQUE(profile_id,user_id));
CREATE INDEX owner_user_lookup ON finanzas.profile_owner(user_id,profile_id);
CREATE TABLE finanzas.authorization_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES finanzas.app_user,profile_id uuid,action text NOT NULL CHECK(action IN('read','write','export','restore','financial-operation')),outcome text NOT NULL CHECK(outcome IN('denied','confirmed')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(profile_id,actor_id)REFERENCES finanzas.profile_owner(profile_id,user_id)ON DELETE RESTRICT);
CREATE TABLE finanzas.operation_receipt(operation_id uuid PRIMARY KEY,actor_id uuid NOT NULL,profile_id uuid NOT NULL,action text NOT NULL CHECK(action IN('write','restore','financial-operation')),fingerprint bytea NOT NULL CHECK(octet_length(fingerprint)=32),result_revision bigint NOT NULL CHECK(result_revision>=0),FOREIGN KEY(profile_id,actor_id)REFERENCES finanzas.profile_owner(profile_id,user_id)ON DELETE RESTRICT);
CREATE FUNCTION finanzas.current_actor()RETURNS uuid LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$SELECT CASE WHEN COALESCE(current_setting('finanzas.actor_id',true),'') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' THEN current_setting('finanzas.actor_id',true)::uuid ELSE NULL END$$;
CREATE FUNCTION finanzas.check_profile_revision()RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$BEGIN IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'REVISION_REQUIRED' USING ERRCODE='40001';END IF;RETURN NEW;END$$;
CREATE TRIGGER profile_revision BEFORE UPDATE ON finanzas.profile FOR EACH ROW EXECUTE FUNCTION finanzas.check_profile_revision();
REVOKE ALL ON SCHEMA finanzas FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA finanzas FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA finanzas FROM PUBLIC;
GRANT USAGE ON SCHEMA finanzas TO finanzas_runtime;
GRANT EXECUTE ON FUNCTION finanzas.current_actor()TO finanzas_runtime;
GRANT SELECT ON finanzas.app_user,finanzas.external_identity,finanzas.profile,finanzas.profile_owner,finanzas.authorization_event,finanzas.operation_receipt TO finanzas_runtime;
GRANT UPDATE(label,revision)ON finanzas.profile TO finanzas_runtime;
GRANT INSERT ON finanzas.authorization_event,finanzas.operation_receipt TO finanzas_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA finanzas REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA finanzas REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['registry_state','app_user','external_identity','profile','profile_owner','authorization_event','operation_receipt']LOOP EXECUTE format('ALTER TABLE finanzas.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE finanzas.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY maintenance ON finanzas.%I TO finanzas_migrator USING(true) WITH CHECK(true)',t);END LOOP;END$$;
CREATE POLICY user_read ON finanzas.app_user FOR SELECT TO finanzas_runtime USING(id=finanzas.current_actor()AND status='active');
CREATE POLICY identity_read ON finanzas.external_identity FOR SELECT TO finanzas_runtime USING(user_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.app_user u WHERE u.id=user_id));
CREATE POLICY owner_read ON finanzas.profile_owner FOR SELECT TO finanzas_runtime USING(user_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.app_user u WHERE u.id=user_id));
CREATE POLICY profile_read ON finanzas.profile FOR SELECT TO finanzas_runtime USING(status='active'AND EXISTS(SELECT 1 FROM finanzas.profile_owner o WHERE o.profile_id=id AND o.user_id=finanzas.current_actor()));
CREATE POLICY profile_write ON finanzas.profile FOR UPDATE TO finanzas_runtime USING(status='active'AND EXISTS(SELECT 1 FROM finanzas.profile_owner o WHERE o.profile_id=id AND o.user_id=finanzas.current_actor()))WITH CHECK(status='active'AND EXISTS(SELECT 1 FROM finanzas.profile_owner o WHERE o.profile_id=id AND o.user_id=finanzas.current_actor()));
CREATE POLICY event_read ON finanzas.authorization_event FOR SELECT TO finanzas_runtime USING(actor_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.app_user u WHERE u.id=actor_id));
CREATE POLICY event_append ON finanzas.authorization_event FOR INSERT TO finanzas_runtime WITH CHECK(actor_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.app_user u WHERE u.id=actor_id)AND(profile_id IS NULL OR EXISTS(SELECT 1 FROM finanzas.profile_owner o WHERE o.profile_id=authorization_event.profile_id AND o.user_id=actor_id)));
CREATE POLICY receipt_read ON finanzas.operation_receipt FOR SELECT TO finanzas_runtime USING(actor_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.app_user u WHERE u.id=actor_id));
CREATE POLICY receipt_append ON finanzas.operation_receipt FOR INSERT TO finanzas_runtime WITH CHECK(actor_id=finanzas.current_actor()AND EXISTS(SELECT 1 FROM finanzas.profile_owner o WHERE o.profile_id=operation_receipt.profile_id AND o.user_id=actor_id));
